      }
    ],
    "lacunas": [],
    "motivo": "Orçamento de referência declarado em R$5.000,00.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "exato",
    "valor": 530000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      },
      {
        "fonte_id": "f_0ad555e744",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_77c5d27cd0",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_e63d1b2e94",
        "localizador": "L02"
      }
    ],
    "lacunas": [],
    "motivo": "Ao orçamento base de 500.000 centavos soma-se a taxa única de troca de 30.000 centavos. Como o término permanece em D10, não incide cobrança por extensão; as fontes delimitam os demais custos do escopo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "exato",
    "valor": 30000,
    "direcao": "aumento",
    "evidencias": [
      {
        "fonte_id": "f_0ad555e744",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "A taxa adicional única de R$300,00 corresponde a 30.000 centavos de aumento sobre a linha base.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso mantém a disponibilidade do cartucho em D2 e registra o aceite de equivalência, sem alterar o procedimento padrão nem as demais condições. Portanto, o término não varia. O custo aumenta apenas pela taxa de troca expressamente informada."
}

